-- 사원 명부 원본 (가상 데이터)
-- 
-- 이 프로젝트는 회사 명부 엑셀을 MySQL 로 임포트해 stg_employee 로 두고,
-- 거기서 부서 · 팀 · 사원을 뽑아 정규화된 테이블로 옮기는 방식으로 초기 데이터를 만들었다.
-- 실행 순서 : 이 파일 -> seed_employee.sql -> seed_leave.sql
-- 
-- 원본 명부에는 주민등록번호 · 계좌번호 · 연봉 · 인사고과 같은 칸도 있었으나,
-- 전자결재가 쓰지 않는 칸이라 여기서는 제외했다. 필요한 11칸만 남긴다.
-- 값은 모두 실습용 가상 데이터다.

DROP TABLE IF EXISTS `stg_employee`;
CREATE TABLE `stg_employee` (
  `사원번호` varchar(255) DEFAULT NULL,
  `이름` varchar(255) DEFAULT NULL,
  `이메일` varchar(255) DEFAULT NULL,
  `부서` varchar(255) DEFAULT NULL,
  `팀` varchar(255) DEFAULT NULL,
  `직급` varchar(255) DEFAULT NULL,
  `직책` varchar(255) DEFAULT NULL,
  `직급레벨` varchar(255) DEFAULT NULL,
  `퇴직구분` varchar(255) DEFAULT NULL,
  `직속상사사원번호` varchar(255) DEFAULT NULL,
  `미사용휴가일수` varchar(255) DEFAULT NULL,
  KEY `idx_code` (`사원번호`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

